import{_ as e,o as n,c as s,a0 as t}from"./chunks/framework.DoRPXVp_.js";const u=JSON.parse('{"title":"ICE Connection & LRP Relay","description":"","frontmatter":{"title":"ICE Connection & LRP Relay"},"headers":[],"relativePath":"design/ice-connection.md","filePath":"design/ice-connection.md"}'),r={name:"design/ice-connection.md"};function i(d,a,p,l,c,o){return n(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="ice-connection-lrp-relay" tabindex="-1">ICE Connection &amp; LRP Relay <a class="header-anchor" href="#ice-connection-lrp-relay" aria-label="Permalink to &quot;ICE Connection &amp; LRP Relay&quot;">​</a></h1><blockquote><p>Source: <code>superpowers/specs/2026-05-01-ice-relay-wireguard-design.md</code>, <code>2026-05-18-ice-handshake-design.md</code></p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Lattice establishes peer-to-peer WireGuard tunnels using a <strong>dual-path race</strong>: ICE (direct UDP) and LRP (relay fallback). NATS carries signaling messages. Both share UDP <code>:51820</code> via <code>FilteringUDPMux</code>.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>          Peer A                                  Peer B</span></span>
<span class="line"><span>      ┌───────────┐                          ┌───────────┐</span></span>
<span class="line"><span>      │   wf0     │                          │   wf0     │</span></span>
<span class="line"><span>      │   TUN     │                          │   TUN     │</span></span>
<span class="line"><span>      └─────┬─────┘                          └─────┬─────┘</span></span>
<span class="line"><span>            │                                      │</span></span>
<span class="line"><span>      ┌─────▼─────┐                          ┌─────▼─────┐</span></span>
<span class="line"><span>      │ WireGuard │                          │ WireGuard │</span></span>
<span class="line"><span>      │  Device   │                          │  Device   │</span></span>
<span class="line"><span>      └─────┬─────┘                          └─────┬─────┘</span></span>
<span class="line"><span>            │                                      │</span></span>
<span class="line"><span>  ┌─────────▼─────────┐                  ┌─────────▼─────────┐</span></span>
<span class="line"><span>  │  FilteringUDPMux   │                  │  FilteringUDPMux   │</span></span>
<span class="line"><span>  │  :51820            │                  │  :51820            │</span></span>
<span class="line"><span>  └──┬─────────────┬──┘                  └──┬─────────────┬──┘</span></span>
<span class="line"><span>     │             │                        │             │</span></span>
<span class="line"><span>┌────▼────┐  ┌─────▼──────┐          ┌────▼────┐  ┌─────▼──────┐</span></span>
<span class="line"><span>│ ICE     │  │ LRP Client │          │ ICE     │  │ LRP Client │</span></span>
<span class="line"><span>│ Agent   │  │ (QUIC/TCP) │          │ Agent   │  │ (QUIC/TCP) │</span></span>
<span class="line"><span>└─────────┘  └─────┬──────┘          └─────────┘  └─────┬──────┘</span></span>
<span class="line"><span>                   └──────── Relay Server ────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>     Signaling: NATS (lattice.signals.peers.&lt;PeerID&gt;)</span></span></code></pre></div><h2 id="ice-handshake-4-message-via-nats" tabindex="-1">ICE Handshake (4-message via NATS) <a class="header-anchor" href="#ice-handshake-4-message-via-nats" aria-label="Permalink to &quot;ICE Handshake (4-message via NATS)&quot;">​</a></h2><p>Initiator is determined by <code>localId &gt; remoteId</code> (numeric uint64 comparison).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Initiator (larger ID)                   Responder (smaller ID)</span></span>
<span class="line"><span>────────────────────────                ───────────────────────</span></span>
<span class="line"><span>Prepare():</span></span>
<span class="line"><span>  getAgent() + GatherCandidates()       Prepare():</span></span>
<span class="line"><span>  send SYN ──────────────────►            (waits for SYN)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                                        Handle(SYN):</span></span>
<span class="line"><span>  ◄─────────────────── ACK               1. extract peer_info</span></span>
<span class="line"><span>                                         2. getAgent()</span></span>
<span class="line"><span>Handle(ACK):                             3. send ACK</span></span>
<span class="line"><span>  GatherCandidates() (if needed)</span></span>
<span class="line"><span>  OFFER(candidate) ──────────►          Handle(OFFER):</span></span>
<span class="line"><span>  ◄────────── ANSWER(candidate)           AddRemoteCandidate()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Dial():                                 Dial():</span></span>
<span class="line"><span>  AwaitConnect()                          AwaitConnect()</span></span>
<span class="line"><span>  ◄══════ ICE Connected ══════►          ◄══════ ICE Connected ══════►</span></span></code></pre></div><ul><li><strong>SYN retry</strong>: every 2s via ticker, stops when ACK received</li><li><strong>SYN + active agent</strong>: responder resends ACK + candidates</li><li><strong>SYN + closed agent</strong>: responder triggers <code>restart()</code> (remote restarted)</li></ul><h2 id="concurrent-race-lrp-fallback" tabindex="-1">Concurrent Race &amp; LRP Fallback <a class="header-anchor" href="#concurrent-race-lrp-fallback" aria-label="Permalink to &quot;Concurrent Race &amp; LRP Fallback&quot;">​</a></h2><p><code>Probe.discover()</code> runs both dialers concurrently:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ICE goroutine ─┐</span></span>
<span class="line"><span>               ├──► result ← first transport to succeed</span></span>
<span class="line"><span>LRP goroutine ─┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Outcome</th><th>Behavior</th></tr></thead><tbody><tr><td>ICE wins</td><td>Return ICE transport immediately</td></tr><tr><td>LRP wins, ICE arrives within 500ms</td><td>Close LRP, return ICE</td></tr><tr><td>LRP wins, ICE arrives after 500ms</td><td>Keep LRP, ICE upgrades later</td></tr><tr><td>Both fail</td><td>Record failure, retry in 10s or close after 60s</td></tr></tbody></table><h2 id="connection-state-machine" tabindex="-1">Connection State Machine <a class="header-anchor" href="#connection-state-machine" aria-label="Permalink to &quot;Connection State Machine&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Created → Probing → ICEReady ─┬→ Failed → Probing (10s retry)</span></span>
<span class="line"><span>                 → LRPReady ─┤         → Closed (60s, permanent)</span></span>
<span class="line"><span>                              │</span></span>
<span class="line"><span>                 LRPReady → ICEReady (transparent upgrade)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td><code>created</code></td><td>Probe allocated</td></tr><tr><td><code>probing</code></td><td>ICE + LRP racing</td></tr><tr><td><code>ice-ready</code></td><td>ICE direct connected</td></tr><tr><td><code>lrp-ready</code></td><td>LRP relay active</td></tr><tr><td><code>failed</code></td><td>All dialers failed</td></tr><tr><td><code>closed</code></td><td>Unreachable for 60s</td></tr></tbody></table><p>Callbacks: <code>Probing→Ready</code> sets WireGuard endpoint + route + NAT; <code>LRPReady→ICEReady</code> only updates endpoint; <code>→Failed/Closed</code> removes peer.</p><h2 id="filteringudpmux" tabindex="-1">FilteringUDPMux <a class="header-anchor" href="#filteringudpmux" aria-label="Permalink to &quot;FilteringUDPMux&quot;">​</a></h2><p>ICE STUN and WireGuard share UDP <code>:51820</code>. Two goroutines read the same <code>net.UDPConn</code>:</p><table tabindex="0"><thead><tr><th>Packet</th><th>ICE agent</th><th>WireGuard</th></tr></thead><tbody><tr><td>STUN (magic <code>0x2112A442</code>)</td><td>✅ dispatched</td><td>❌ decrypt fails</td></tr><tr><td>WireGuard encrypted</td><td>❌ no ufrag match</td><td>✅ dispatched</td></tr></tbody></table><p><code>FilteringUDPMux</code> inspects bytes 4-7 for the STUN magic cookie and routes accordingly. After ICE succeeds, the agent closes and WG <code>PersistentKeepalive</code> maintains NAT.</p><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>internal/server/transport/state_machine.go</code></td><td>State machine</td></tr><tr><td><code>internal/server/transport/ice_dialer.go</code></td><td>ICE dialer (SYN/ACK/OFFER/ANSWER)</td></tr><tr><td><code>internal/server/transport/probe.go</code></td><td>Per-peer probe, discover() race</td></tr><tr><td><code>internal/server/transport/probe_factory.go</code></td><td>Probe lifecycle, callbacks</td></tr><tr><td><code>internal/server/transport/lrp_dialer.go</code></td><td>LRP relay dialer (QUIC+TCP)</td></tr><tr><td><code>internal/agent/infra/mux_filter.go</code></td><td>FilteringUDPMux</td></tr></tbody></table>`,24)])])}const g=e(r,[["render",i]]);export{u as __pageData,g as default};
